function renderCompact(){if(draft.created)return app(modal(success(),'compact'));if(draft.step===0)return app(modal(`<p class="section-title">Choose how this client is set up</p><p class="section-copy">Monthly services or a custom plan and task list.</p>${modeChoices(true)}`,'compact',footer()));return app(modal(`${modeChoices(true)}<details class="accordion" open><summary>Client details <span>Name, owner & dates</span></summary><div class="inner">${details()}</div></details><details class="accordion" open><summary>${draft.mode==='Monthly'?'Monthly services':'Plan & tasks'} <span>${draft.mode==='Monthly'?draft.hours+'h · '+draft.content+' content':tasks().length+' tasks'}</span></summary><div class="inner">${draft.mode==='Monthly'?monthly():custom()}</div></details><details class="accordion"><summary>Setup summary <span>Review before creating</span></summary><div class="inner">${summaryRows()}</div></details>`,'compact',footer('Create client →','create')));}
